import{_ as e,o,c as r,ai as t}from"./chunks/framework.DAbPic9L.js";const u=JSON.parse('{"title":"领域驱动设计","description":"","frontmatter":{},"headers":[],"relativePath":"microservices/temp.md","filePath":"microservices/temp.md","lastUpdated":1778735525000}'),l={name:"microservices/temp.md"};function i(d,a,h,n,p,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="领域驱动设计" tabindex="-1">领域驱动设计 <a class="header-anchor" href="#领域驱动设计" aria-label="Permalink to &quot;领域驱动设计&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="学习总论" tabindex="-1">学习总论 <a class="header-anchor" href="#学习总论" aria-label="Permalink to &quot;学习总论&quot;">​</a></h2><p>简要概括: 领域问题驱动领域模型，领域模型驱动软件设计。</p><h3 id="领域" tabindex="-1">领域 <a class="header-anchor" href="#领域" aria-label="Permalink to &quot;领域&quot;">​</a></h3><p>在领域驱动设计中，领域指的就是软件系统要解决业务问题的范围边界。这些业务问题的解决，对于软件系统的用户来讲是有价值的，也是用户最关注的内容，</p><p>通俗来讲，我们所谈的业务内容、业务问题、功能需求等，都是来源于领域问题的真实写照。唯一需要明确辨别领域问题是有效意义需求；无效的业务问题得尽早切除，避免思维设计自洽。</p><h3 id="方法论" tabindex="-1">方法论 <a class="header-anchor" href="#方法论" aria-label="Permalink to &quot;方法论&quot;">​</a></h3><p>领域驱动设计的核心方法论: 领域问题驱动领域模型，领域模型驱动软件设计。</p><p>一切要从领域问题出发，通过<code>单一职责原则</code>、<code>开放封闭原则</code>、<code>依赖反转原则</code>等设计原则，使程序高内聚低耦合，职责分明；从而得出一个可以解决领域问题的软件系统。</p><p><strong>三大设计原则</strong></p><ul><li>单一职责原则: 一个类只负责引起它变化的职责(确定类的属性、方法)。</li><li>开放封闭原则: 对扩展开放、对修改封闭(依赖抽象，程序扩展不改原有代码，提供热插拨扩展)。</li><li>依赖反转原则: 程序之间只依赖抽象接口，而不依赖于具体实现(内部依赖抽象，外部具体实现)。</li></ul><h3 id="应用优势" tabindex="-1">应用优势 <a class="header-anchor" href="#应用优势" aria-label="Permalink to &quot;应用优势&quot;">​</a></h3><p>领域驱动设计，它把业务操作统一封装成软件系统可适配支持的命令，基于命令构建聚合仓储，执行内部业务逻辑，并通过领域事件通知外部系统。</p><p>它明确了领域范围边界，不依赖外部系统；也明确了领域职责分离，技术实现解耦；程序员只需专注业务问题的逻辑处理。</p><p>技术实现采用领域语言来表达解决问题的过程，从而提高软件开发的可读性与可维护性。即使新手接触项目，也能快速理解业务，投身程序开发。</p><p><strong>领域驱动设计的实践方式</strong></p><p>通过不同的架构模式解决不同流程切面的构建问题。</p><ul><li>事件风暴确定领域事件</li></ul><p>领域事件描述了领域模型有业务价值的状态变化。</p><p>无业务价值的状态变化，不需要定义为领域事件；这是由于高频并发过程中，会引起消息队列数量庞大，消息阻塞；且浪费系统流量。</p><p>比如，用户通过帐户密码登录失败，触发登录失败事件，可写入系统日志，但没必要丢到消息队列中；只要累计登录失败超限次数，会触发账户锁定事件，写入消息队列；用户可联系管理员人工处理，并触发账户解锁事件。</p><ul><li>领域事件衍射模型命令</li></ul><p>领域模型只接收命令，执行相应解决问题的业务逻辑，而这过程不对外开发。</p><p>聚合是对外开放的唯一入口，通过具体命令来驱动领域模型执行业务逻辑。</p><ul><li>领域职责分离实现</li></ul><p>领域命令描述了领域模型状态变化的事实。</p><p>外部查询数据，应当通过适配接口获取相关内容。</p><p>实体语义逻辑操作，解决领域问题(业务操作，状态流转)。</p><p>值对象约束业务规则，保证数据合法性。</p><ul><li>标识索引构建聚合</li></ul><p>由于领域模型规定保证数据一致性，但过多的对象聚合导致对象臃肿，聚合构建开销大。</p><p>因此，建议根据领域模型的职责边界划分不同聚合，以减少聚合构建的开销问题。</p><p>聚合构建，一般可通过标识索引来寻找关联关系来构建。</p><ul><li>特别提醒思维转变</li></ul><p>抛弃过时的四层架构(<code>上层依赖下层</code>)思维，建议通过依赖反转设计抽象接口解耦具体实现。</p><p>领域驱动设计，根据设计三大原则，实现领域边界职责分明，程序高内聚低耦合，通用清晰语义操作，帮助构建出易扩展、高性能的软件系统。</p><h3 id="实践必备" tabindex="-1">实践必备 <a class="header-anchor" href="#实践必备" aria-label="Permalink to &quot;实践必备&quot;">​</a></h3><p>领域驱动设计，得益于前人经验思维总结和框架实现集成，使得开发前期设计成本大大降低。</p><p>另外，它明确了领域边界、职责分离，业务语义，使业务复杂性趋向简单化。程序员只需专注领域业务的逻辑实现，从而快速构建软件系统。</p><p>特别提醒: 在领域驱动设计中，程序员最重要的不是具体技术实现的能力，而是领域模型构建的能力。</p><h2 id="历史演进" tabindex="-1">历史演进 <a class="header-anchor" href="#历史演进" aria-label="Permalink to &quot;历史演进&quot;">​</a></h2><p><strong>概念来源</strong></p><h3 id="_2003-年" tabindex="-1">2003 年 <a class="header-anchor" href="#_2003-年" aria-label="Permalink to &quot;2003 年&quot;">​</a></h3><p>最早由<code>Eric Evans</code>提出，出自《领域驱动设计: 软件核心复杂性应对之道》一书。</p><h3 id="_2004-年" tabindex="-1">2004 年 <a class="header-anchor" href="#_2004-年" aria-label="Permalink to &quot;2004 年&quot;">​</a></h3><p><strong>四色建模(<code>Four Color Modeling</code>)</strong></p><p>贡献者: 彼得·琼斯</p><p>四色建模通过四种颜色（<code>粉色、黄色、蓝色、绿色</code>）对领域模型进行分类，帮助团队更好地理解和组织复杂的业务逻辑。</p><h3 id="_2005-年" tabindex="-1">2005 年 <a class="header-anchor" href="#_2005-年" aria-label="Permalink to &quot;2005 年&quot;">​</a></h3><p><strong>六边形架构(<code>Hexagonal Architecture</code>)</strong></p><p>贡献者: 阿利斯泰尔·科克本</p><p>六边形架构强调分离核心业务逻辑与外部系统（如数据库、<code>API</code>等），通过端口和适配器实现解耦。</p><p>它为<code>DDD</code>提供了一种清晰的架构模式，帮助开发者将领域逻辑与基础设施分离。</p><p><strong>事件溯源(<code>Event Sourcing</code>)</strong></p><p>贡献者: 格雷格·杨</p><p>事件溯源通过记录状态变化的事件序列来还原系统状态，与<code>DDD</code>的领域事件(<code>Domain Events</code>)概念结合，能够更好地实现系统的可追溯性和一致性。</p><h3 id="_2009-年" tabindex="-1">2009 年 <a class="header-anchor" href="#_2009-年" aria-label="Permalink to &quot;2009 年&quot;">​</a></h3><p><strong>DCI(<code>Data Context Interaction</code>)</strong></p><p>贡献者: 特赖格夫·里亚姆斯内斯</p><p><code>DCI</code>强调将数据、上下文和交互分离，帮助团队更好地组织领域模型，与<code>DDD</code>的聚合和限界上下文形成互补。</p><h3 id="_2010-年" tabindex="-1">2010 年 <a class="header-anchor" href="#_2010-年" aria-label="Permalink to &quot;2010 年&quot;">​</a></h3><p><strong>CQRS(<code>Command Query Responsibility Segregation</code>)</strong></p><p>贡献者： 格雷格·杨</p><p><code>CQRS</code>将读写操作分离，允许不同的模型处理命令和查询。</p><p>这与<code>DDD</code>的限界上下文(<code>Bounded Context</code>)和聚合(<code>Aggregate</code>)概念高度契合，帮助优化复杂系统的性能和可维护性。</p><p><strong>LMAX架构</strong></p><p>贡献者: 马丁·汤普森</p><p><code>LMAX</code>架构通过事件驱动的方式实现高吞吐量和低延迟，与<code>DDD</code>的领域事件和<code>CQRS</code>结合，为高性能系统提供了设计参考。</p><p><strong>领域叙事(<code>Domain Storytelling</code>)</strong></p><p>贡献者: 斯特凡·霍斯特曼</p><p>领域叙事通过故事和场景描述业务需求，帮助团队更好地理解领域逻辑，并与<code>DDD</code>的通用语言(<code>Ubiquitous Language</code>)相结合。</p><h3 id="_2013-年" tabindex="-1">2013 年 <a class="header-anchor" href="#_2013-年" aria-label="Permalink to &quot;2013 年&quot;">​</a></h3><p><strong>事件风暴(<code>Event Storming</code>)</strong></p><p>贡献者: 阿尔贝托·布兰多利尼</p><p>事件风暴是一种协作式工作坊方法，帮助团队快速发现领域事件、命令和聚合。它为<code>DDD</code>的需求分析和模型设计提供了高效的实践工具。</p><h3 id="_2014-年" tabindex="-1">2014 年 <a class="header-anchor" href="#_2014-年" aria-label="Permalink to &quot;2014 年&quot;">​</a></h3><p><strong>微服务(<code>Microservices</code>)</strong></p><p>贡献者: 马丁·福勒</p><p>微服务与<code>DDD</code>的限界上下文紧密结合，帮助团队将复杂系统拆分为独立部署的服务单元。DDD为微服务的边界划分提供了理论支持。</p><h2 id="领域建模" tabindex="-1">领域建模 <a class="header-anchor" href="#领域建模" aria-label="Permalink to &quot;领域建模&quot;">​</a></h2><p>现代敏捷开发(<code>快速产出、能跑就行</code>)环境下，程序员能见到的大多都是一堆需求功能列表，项目文档说明，领导愿望期待，剩下的都交给程序员自己捣鼓实现，偶尔领导还会追加无效需求和更改命令。这种现象揭示了两个最大问题: 如何确定有效需求的领域问题，如何确定对象关联与流程逻辑；以上现象没人能清楚表达描述。</p><p>在领域驱动设计中，领域建模是最难也是最容易被忽略的过程环节。</p><p>领域建模，就是针对领域问题分析，确定有效意义的需求功能；然后设计领域模型，明确领域对象的关联关系，以及业务具体的规则约束和流程逻辑；让软件系统当前可知可控，未来可迭代维护扩展。因此，程序员必备解决以上两个问题的能力；而领域驱动设计的方法论提供了低成本、高效率的软件开发方法来解决这些问题。</p><p><strong>程序员必会能力</strong></p><ul><li>结合项目说明书、客户需求表达等内容完成需求分析，构建业务场景，规划有效意义的需求功能列表。</li><li>通过领域驱动设计方法论，构建领域模型，明确领域对象关联关系，以及业务具体的规则约束和流程逻辑。</li></ul><p><strong>领域驱动设计建议</strong></p><p>在领域建模过程中，应当同领域专家一起讨论，以便更好地理解业务需求，并将其转换为领域模型。</p><p>业务需求的提供者，一般是领域专家。领域专家有可能是产品客户、行业专家、产品经理，以及程序员等人群。</p><p>在多人协作场景下，建议规范通用语言，统一术语，编程语义，可减少沟通成本，避免鸡同鸭讲。</p><p>通过战略设计(<code>业务领域划分和职责边界确定</code>)明确领域要素和职责边界，将复杂业务简单化，以便未来可迭代扩展；</p><p>通过战术设计(<code>领域模型构建和具体技术实现</code>)明确业务规则约束和流程编排，保持系统细节一致性、灵活性以及可维护性。</p><h3 id="领域模型" tabindex="-1">领域模型 <a class="header-anchor" href="#领域模型" aria-label="Permalink to &quot;领域模型&quot;">​</a></h3><p>领域模型是针对领域问题设计的模型。它是领域问题的解决方案，同时它忽略了很多技术实现细节。</p><h4 id="领域事件" tabindex="-1">领域事件 <a class="header-anchor" href="#领域事件" aria-label="Permalink to &quot;领域事件&quot;">​</a></h4><p>领域事件，描述领域模型内部具有价值意义的状态变化。</p><p>简而言之，它是一个已发生的不可变事实，保证了系统内部的一致性。</p><p>从时间轴上看，一系列领域事件的发生，就形成了领域模型业务操作的历史记录。</p><p>当然，现实行为中可能存在误操作，但它仍然是不可变的事实。想要消除误操作的领域事件，只能通过另一个领域事件来抵消操作。比如<code>订单已支付(扣款)</code>与<code>支付撤销(退款)</code>。</p><p>通过领域事件的学习，有助于理解领域建模中事件驱动的业务流程，理解领域模块内部及外部之间的业务交互。</p><p><strong>特别提醒</strong></p><ul><li>领域事件是用户行为的结果(<code>状态变化已变更</code>)，通过具体领域命令触发。</li><li>领域事件的命名范式，采用<code>过去式</code>命名，即表示用户行为的结果。</li><li>只有领域模型状态变化所引起的事实事件，才应该定义为领域事件；另外一种是政策要求程序合规，可定义领域事件。其它形式的事件，不能定义为领域事件；否则可能造成消息队列的膨胀与延迟。</li></ul><h4 id="领域命令" tabindex="-1">领域命令 <a class="header-anchor" href="#领域命令" aria-label="Permalink to &quot;领域命令&quot;">​</a></h4><p>领域命令，描述用户操作领域模型解决某个具体领域问题的指令。</p><p>通俗来讲，领域模型不对外开放，而是通过领域聚合对外开放唯一入口；领域聚合通过执行领域模型具体命令解决某项领域问题。</p><p>特别注意，在改变领域模型状态过程中，请将业务操作语义成领域命令来触发。</p><p><strong>特别提醒</strong></p><ul><li>领域命令是外部主动触发领域模型解决某项领域问题的唯一的办法。</li><li>领域命令，往往会触发领域事件的发布；这是因为领域模型的状态变化所决定的。</li><li>外部触发查询操作，而查询操作不会造成领域模型状态变化，因此不应该定义为领域命令；而是通过接口查询数据内容。</li></ul><h4 id="领域聚合" tabindex="-1">领域聚合 <a class="header-anchor" href="#领域聚合" aria-label="Permalink to &quot;领域聚合&quot;">​</a></h4><p>领域聚合，是领域模型的核心单元，解决领域模型状态一致性问题。</p><p>领域聚合是对外开放的唯一入口，外部对象只能通过领域聚合改变领域模型的内部状态。</p><p>为了方便管理领域聚合操作所影响的状态变化，会将紧密相关的领域实体和领域值对象放在同一个领域聚合内。领域模型的状态变化，会将本次变更作为事务记录，发布领域事件，确保领域模型状态的最终一致性。</p><h4 id="领域实体" tabindex="-1">领域实体 <a class="header-anchor" href="#领域实体" aria-label="Permalink to &quot;领域实体&quot;">​</a></h4><p>在领域模型中，领域值实体通过唯一标识定义身份，唯一标识在生命周期中始终保持不变。唯一标识全等，就视为同一个对象。另外，它将以充血模型定义一组有关其属性状态和业务行为的字段内容，并通过行为来保护不变条件和业务规则。</p><p><strong>特别提醒</strong></p><ul><li>领域实体与库表实体并不是一一对应关系；因为领域实体可能由多个库表实体组成；而库表实体代表一条记录。</li></ul><h4 id="领域值对象" tabindex="-1">领域值对象 <a class="header-anchor" href="#领域值对象" aria-label="Permalink to &quot;领域值对象&quot;">​</a></h4><p>在领域模型中，领域值对象通过属性值定义身份，但不具有生命周期。属性值全等，就视为同一个对象。另外，领域值对象时不可变，且不提供修改自身属性状态的方法；并在创建时自动验证业务规则约束。</p><p><strong>特别提醒</strong></p><ul><li>不可变性是值对象的基础；不修改自身是值对象的行为准则；自验证是值对象的品质保证。</li><li>自动验证的常见规则约束: 枚举值、格式值、支持值、数据类型、长度限制等。</li><li>定义领域值对象时，可通过<code>readonly</code>标识或通过<code>Object.freeze()</code>冻结对象。当然，可将一组关联的属性状态归纳为一个值对象。</li></ul><h4 id="领域服务" tabindex="-1">领域服务 <a class="header-anchor" href="#领域服务" aria-label="Permalink to &quot;领域服务&quot;">​</a></h4><p>领域服务，是领域模型的无状态协调者；它封装了不适合放在领域实体、领域值对象中的业务逻辑；一般涉及跨多个领域对象的业务操作。</p><p>对于跨多个领域对象的业务规则、复杂计算逻辑、策略模式的实现、领域对象的创建逻辑等场景，可以考虑封装成领域服务。</p><p><strong>特别提醒</strong></p><ul><li>领域服务的无状态，意味着它不持有任何属性状态，也不依赖于任何外部资源；它只能通过方法参数来引用其它领域对象来完成业务逻辑。</li></ul><h4 id="流程管理器" tabindex="-1">流程管理器 <a class="header-anchor" href="#流程管理器" aria-label="Permalink to &quot;流程管理器&quot;">​</a></h4><h3 id="事件风暴" tabindex="-1">事件风暴 <a class="header-anchor" href="#事件风暴" aria-label="Permalink to &quot;事件风暴&quot;">​</a></h3><h2 id="技术实现" tabindex="-1">技术实现 <a class="header-anchor" href="#技术实现" aria-label="Permalink to &quot;技术实现&quot;">​</a></h2><h3 id="架构模式" tabindex="-1">架构模式 <a class="header-anchor" href="#架构模式" aria-label="Permalink to &quot;架构模式&quot;">​</a></h3><h4 id="端口适配" tabindex="-1">端口适配 <a class="header-anchor" href="#端口适配" aria-label="Permalink to &quot;端口适配&quot;">​</a></h4><h4 id="命令查询职责分离" tabindex="-1">命令查询职责分离 <a class="header-anchor" href="#命令查询职责分离" aria-label="Permalink to &quot;命令查询职责分离&quot;">​</a></h4><h4 id="事件溯源" tabindex="-1">事件溯源 <a class="header-anchor" href="#事件溯源" aria-label="Permalink to &quot;事件溯源&quot;">​</a></h4><h4 id="lmax" tabindex="-1">LMAX <a class="header-anchor" href="#lmax" aria-label="Permalink to &quot;LMAX&quot;">​</a></h4><h4 id="orm" tabindex="-1">ORM <a class="header-anchor" href="#orm" aria-label="Permalink to &quot;ORM&quot;">​</a></h4><h4 id="事务" tabindex="-1">事务 <a class="header-anchor" href="#事务" aria-label="Permalink to &quot;事务&quot;">​</a></h4><h4 id="四层架构" tabindex="-1">四层架构 <a class="header-anchor" href="#四层架构" aria-label="Permalink to &quot;四层架构&quot;">​</a></h4><h3 id="领域对象" tabindex="-1">领域对象 <a class="header-anchor" href="#领域对象" aria-label="Permalink to &quot;领域对象&quot;">​</a></h3><h4 id="值对象" tabindex="-1">值对象 <a class="header-anchor" href="#值对象" aria-label="Permalink to &quot;值对象&quot;">​</a></h4><h4 id="领域事件-1" tabindex="-1">领域事件 <a class="header-anchor" href="#领域事件-1" aria-label="Permalink to &quot;领域事件&quot;">​</a></h4><h4 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h4><h4 id="聚合" tabindex="-1">聚合 <a class="header-anchor" href="#聚合" aria-label="Permalink to &quot;聚合&quot;">​</a></h4><h4 id="服务" tabindex="-1">服务 <a class="header-anchor" href="#服务" aria-label="Permalink to &quot;服务&quot;">​</a></h4><h4 id="工厂" tabindex="-1">工厂 <a class="header-anchor" href="#工厂" aria-label="Permalink to &quot;工厂&quot;">​</a></h4><h4 id="仓储" tabindex="-1">仓储 <a class="header-anchor" href="#仓储" aria-label="Permalink to &quot;仓储&quot;">​</a></h4><h4 id="监听器" tabindex="-1">监听器 <a class="header-anchor" href="#监听器" aria-label="Permalink to &quot;监听器&quot;">​</a></h4>',146)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
